function describe(node, depth) {
  const pad = '  '.repeat(depth);
  let info = `${pad}${node.type} "${node.name}" x:${node.x} y:${node.y} w:${node.width} h:${node.height}`;
  if (node.type === 'TEXT') {
    info += ` fontSize:${node.fontSize} fontName:${JSON.stringify(node.fontName)} chars:"${node.characters}" fills:${JSON.stringify(node.fills)}`;
  }
  if ('fills' in node && node.type !== 'TEXT') {
    info += ` fills:${JSON.stringify(node.fills)}`;
  }
  if ('strokes' in node && node.strokes && node.strokes.length) {
    info += ` strokes:${JSON.stringify(node.strokes)} strokeWeight:${node.strokeWeight}`;
  }
  if ('cornerRadius' in node) {
    info += ` cornerRadius:${JSON.stringify(node.cornerRadius)}`;
  }
  if ('layoutMode' in node) {
    info += ` layoutMode:${node.layoutMode} padding:${node.paddingLeft}/${node.paddingRight}/${node.paddingTop}/${node.paddingBottom} itemSpacing:${node.itemSpacing} primaryAxisAlign:${node.primaryAxisAlignItems} counterAxisAlign:${node.counterAxisAlignItems}`;
  }
  let out = info + '\n';
  if ('children' in node) {
    for (const child of node.children) {
      out += describe(child, depth + 1);
    }
  }
  return out;
}

