function hex(h, a=1){
  h = h.replace('#','');
  const r = parseInt(h.substring(0,2),16)/255;
  const g = parseInt(h.substring(2,4),16)/255;
  const b = parseInt(h.substring(4,6),16)/255;
  return {r,g,b,a};
}
function solid(h){ const c = hex(h); return {type:'SOLID', color:{r:c.r,g:c.g,b:c.b}, opacity:1}; }

// Create paint styles for the shared color system
const paletteDefs = [
  ['Ink / Black', '#000000'],
  ['Ink / Near Black (text primary)', '#111113'],
  ['Text / Secondary', '#6B6B72'],
  ['Text / Tertiary', '#9A9AA3'],
  ['Surface / White', '#FFFFFF'],
