  ['Accent / Sale Red', '#E0383E'],
  ['Accent / Star Gold', '#FFB400'],
  ['Accent / Success Green', '#1FAA59'],
];
const existing = await figma.getLocalPaintStylesAsync();
const styleMap = {};
for (const [name, h] of paletteDefs) {
  let st = existing.find(s => s.name === name);
  if (!st) {
    st = figma.createPaintStyle();
    st.name = name;
  }
  st.paints = [solid(h)];
  styleMap[name] = st.id;
}

