function solid(h, o=1){
  h = h.replace('#','');
  const r = parseInt(h.substring(0,2),16)/255;
  const g = parseInt(h.substring(2,4),16)/255;
  const b = parseInt(h.substring(4,6),16)/255;
  return {type:'SOLID', color:{r,g,b}, opacity:o};
}
function text(chars, size, style, color){
  const t = figma.createText();
  t.fontName = {family:"Inter", style};
  t.fontSize = size;
  t.characters = chars;
  t.fills = [solid(color)];
  return t;
}
function vFixedW(name, width, spacing){
  const f = figma.createFrame(); f.name=name; f.layoutMode='VERTICAL';
  f.resize(width, 10);
  f.counterAxisSizingMode='FIXED'; f.primaryAxisSizingMode='AUTO';
  f.itemSpacing=spacing; f.fills=[];
  return f;
}
function hFixedW(name, width, spacing){
  const f = figma.createFrame(); f.name=name; f.layoutMode='HORIZONTAL';
  f.resize(width, 10);
  f.primaryAxisSizingMode='FIXED'; f.counterAxisSizingMode='AUTO';
  f.itemSpacing=spacing; f.fills=[];
  return f;
}
function sectionWrap(name, padTop, padBottom, bg){
  const s = figma.createFrame(); s.name=name; s.layoutMode='VERTICAL';
  s.resize(1440, 10);
  s.counterAxisSizingMode='FIXED'; s.primaryAxisSizingMode='AUTO';
  s.paddingTop=padTop; s.paddingBottom=padBottom; s.paddingLeft=80; s.paddingRight=80;
  s.counterAxisAlignItems='CENTER'; s.fills = bg?[solid(bg)]:[];
  return s;
}

