async function buildStepper(currentIndex){
  const stepItemMaster = figma.root.findOne(n => n.type === 'COMPONENT' && n.name === 'Checkout Step Item');
  const icons = ['1:218','1:220','1:219'];
  const labels = ['Address','Shipping','Payment'];
  const row = hHug('Checkout Stepper', 16);
  row.counterAxisAlignItems = 'CENTER';
  for (let i = 0; i < 3; i++) {
    const inst = stepItemMaster.createInstance();
    row.appendChild(inst);
    const circle = inst.findOne(n => n.name === 'Circle');
    const label = inst.findOne(n => n.name === 'Label');
    const iconMaster = await figma.getNodeByIdAsync(icons[i]);
    const iconChild = circle.children[0];
    iconChild.swapComponent(iconMaster);
    label.characters = labels[i];
    if (i === currentIndex) {
      circle.fills = [solid('#111113')];
      label.fills = [solid('#111113')];
      label.fontName = {family:'Inter', style:'Semi Bold'};
    } else {
      circle.fills = [solid('#F0F0F2')];
      label.fills = [solid('#9A9AA3')];
      label.fontName = {family:'Inter', style:'Medium'};
    }
    if (i < 2) {
      const line = figma.createRectangle();
      line.resize(60,2);
      line.fills = [solid(i < currentIndex ? '#111113' : '#E4E4E8')];
      row.appendChild(line);
    }
  }
  return row;
}

