const results = [];
async function wire(nodeId, destKey, label){
  try {
    const node = await figma.getNodeByIdAsync(nodeId);
    if (!node) { results.push(`MISSING ${nodeId} (${label})`); return; }
    await node.setReactionsAsync(nav(DEST[destKey]));
